mapper.select:
SELECT P.CMS_CATLG_ID , TRIM(TO_CHAR(P.CATLG_SEQ)) AS CATLG_SEQ , P.CMS_CATLG_ID || '-' || LPAD(TO_CHAR(P.CATLG_SEQ), 5, '0') AS BUY_INFO_ID , LPAD(TO_CHAR(P.CATLG_SEQ), 5, '0') AS BUY_INFO_SEQ /* 구매정보코드 : 화면 표기는 순번만 쓴다(상품정보코드는 옆 열에 있다) */ , C.DESCRIPTION_LOC AS DESCRIPTION_LOC , C.MODEL_INFO AS MODEL_INFO , C.SPECIFICATION AS SPECIFICATION , (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M104' AND MD.CODE = C.MAKER_CODE) AS MAKER_NAME , (SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M001' AND MD.CODE = C.ORIGIN_CODE) AS ORIGIN_NAME , C.ORDER_MEASURE AS MEASURE , P.AGENT AS AGENT , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = P.AGENT) AS VENDOR_NAME , RTRIM(TO_CHAR(P.BUY_PRICE, 'FM999,999,999,990.99999'), '.') AS BUY_PRICE , RTRIM(TO_CHAR(P.MIN_ORDER_QTY, 'FM999,999,990.999'), '.') AS MIN_ORDER_QTY , RTRIM(TO_CHAR(P.PUR_UNIT_QTY, 'FM999,999,990.999'), '.') AS PUR_UNIT_QTY , (SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M034' AND MD.CODE = P.PROCESS_TYPE) AS PROCESS_TYPE , (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M186' AND MD.CODE = P.DELIVERY_TYPE) AS DELIVERY_TYPE , (SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'W001' AND MD.TEXT1 = P.WAREHOUSE_CODE) AS WAREHOUSE_NAME , P.CMS_CATLG_ID || '-' || LPAD(TO_CHAR(P.CATLG_SEQ), 5, '0') AS TCODE FROM CMSPRICE P, CMSCATLG C WHERE P.CMS_CATLG_ID = C.CMS_CATLG_ID AND P.STATUS = 'C'
AND P.CMS_CATLG_ID || '-' || LPAD(TO_CHAR(P.CATLG_SEQ), 5, '0') != #{st_exclude}
AND P.CMS_CATLG_ID || '-' || LPAD(TO_CHAR(P.CATLG_SEQ), 5, '0') LIKE '%' || #{st_buy_code} || '%'
AND C.DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND C.MODEL_INFO LIKE '%' || #{st_model_no} || '%'
AND C.SPECIFICATION LIKE '%' || #{st_spec} || '%'
AND C.MAKER_CODE = #{st_maker_code}
AND EXISTS (SELECT 1 FROM CMSCATEG CG WHERE CG.CMS_CATEG_ID = C.CMS_CATEG_ID AND CG.STATUS != 'D' AND CG.SG_ID IN
#{item}
)
AND C.CMS_CATEG_ID IN
#{item}
AND P.PROCESS_TYPE = DECODE(#{st_process_type}, 'TR', '2', 'DIRECT', '0', #{st_process_type})
AND P.DELIVERY_TYPE = #{st_delivery_type}
AND C.ORDER_MEASURE = #{st_measure}
ORDER BY P.CMS_CATLG_ID, P.CATLG_SEQ

mapper.update:

/*updateMasterMdCmCmsBuyInfoMapMove*/
UPDATE ICOMCQDT
   SET CMS_CATLG_ID = SUBSTR(#{st_to_buy_info}, 1, INSTR(#{st_to_buy_info}, '-') - 1)
     , CATLG_SEQ    = TO_NUMBER(SUBSTR(#{st_to_buy_info}, INSTR(#{st_to_buy_info}, '-') + 1))
     , CHANGE_DATE  = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME  = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE BUYER        = #{BUYER_CODE}
   AND CONTRACT_NO  = #{CONTRACT_NO}
   AND CONTRACT_SEQ = #{CONTRACT_SEQ}
   AND CMS_CATLG_ID = SUBSTR(#{st_from_buy_info}, 1, INSTR(#{st_from_buy_info}, '-') - 1)
   AND CATLG_SEQ    = TO_NUMBER(SUBSTR(#{st_from_buy_info}, INSTR(#{st_from_buy_info}, '-') + 1))

mapper.select:

/*selectMasterMdCmCmsBuyInfoMapMoveBlockCnt*/
SELECT COUNT(*)
  FROM ICOMCQDT Q
 WHERE Q.BUYER        = #{BUYER_CODE}
   AND Q.CONTRACT_NO  = #{CONTRACT_NO}
   AND Q.CONTRACT_SEQ = #{CONTRACT_SEQ}
   AND NVL(Q.CSV_YN, 'N') = 'Y'
   AND NVL(Q.AGENT, ' ') <> NVL((SELECT P.AGENT FROM CMSPRICE P
                                  WHERE P.CMS_CATLG_ID = SUBSTR(#{st_to_buy_info}, 1, INSTR(#{st_to_buy_info}, '-') - 1)
                                    AND P.CATLG_SEQ    = TO_NUMBER(SUBSTR(#{st_to_buy_info}, INSTR(#{st_to_buy_info}, '-') + 1))), ' ')

/*selectMasterMdCmCmsBuyInfoMapFormList*/ SELECT Q.CMS_CATLG_ID , Q.CMS_CATLG_ID || '-' || LPAD(TO_CHAR(Q.CATLG_SEQ), 5, '0') AS BUY_INFO_ID , LPAD(TO_CHAR(Q.CATLG_SEQ), 5, '0') AS BUY_INFO_SEQ /* 구매정보코드 : 화면 표기는 순번만 쓴다(상품정보코드는 옆 열에 있다) */ , (SELECT G.COMORG_CODE FROM KEP.BYCAORGL G WHERE G.COMORG_CODE = (SELECT CMPY.BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = Q.BUYER)) AS GROUP_CODE , (SELECT G.COMORG_NAME FROM KEP.BYCAORGL G WHERE G.COMORG_CODE = (SELECT CMPY.BYCA_COMORG_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = Q.BUYER)) AS GROUP_NAME , Q.BUYER AS BUYER_CODE , (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = Q.BUYER) AS BUYER_NAME , Q.BUYER_ITEM_NO AS BUYER_ITEM_NO , NVL(Q.CSV_YN, 'N') AS CSV_YN , Q.CONTRACT_NO AS CONTRACT_NO , Q.CONTRACT_SEQ AS CONTRACT_SEQ , Q.AGENT AS AGENT FROM ICOMCQDT Q WHERE (Q.CMS_CATLG_ID, Q.CATLG_SEQ) IN
(SUBSTR(#{item}, 1, INSTR(#{item}, '-') - 1), TO_NUMBER(SUBSTR(#{item}, INSTR(#{item}, '-') + 1)))
ORDER BY Q.CMS_CATLG_ID, Q.CATLG_SEQ, Q.BUYER, Q.CONTRACT_NO, Q.CONTRACT_SEQ
